class Client:
    def __init__(self, model, cli=None, sp=None, **kwargs):
        "Basic LLM messages client."
        self.model,self.use = model,usage(0,0)
        self.sp = sp
        self.c = cli or self.genai_client(**kwargs)
    @classmethod
    def genai_client(cls, **kwargs):
        return genai.Client(api_key=kwargs.get('api_key', os.environ.get('GEMINI_API_KEY', None)))


