@patch
@delegates(Models.generate_content)
def __call__(self:Client,
             msgs:list, # List of messages in the dialog
             sp:str=None, # System prompt
             maxtok=4096, # Maximum tokens
             stream:bool=False, # Stream response?
             **kwargs):
    "Make a call to LLM."
    if sp: self.sp = sp
    msgs = self._precall(msgs)
    gc_kwargs = {k: v for k, v in kwargs.items() if k in GenerateContentConfig.model_fields}
    gen_config = GenerateContentConfig(system_instruction=self.sp, max_output_tokens=maxtok, **gc_kwargs)
    gc = self.c.models.generate_content_stream if stream else self.c.models.generate_content
    r = gc(model=self.model, contents=msgs, config=gen_config)
    if not stream: return self._r(r)
    else: return get_stream(map(self._r, r))

