@patch(as_prop=True)
def cost(self:Client):
    inp_cost, out_cost, cache_cost = get_pricing(self.model.split('-exp-')[0], (u := self.use))
    return ((u.prompt_token_count or 0) * inp_cost + (u.candidates_token_count or 0) * out_cost + (u.cached_content_token_count or 0) * cache_cost) / 1e6

