def media_msg(fn: Path, *, cli:genai.Client|None=None, **kw)->dict:
    if isinstance(fn, dict): return fn # Already processed
    f = (cli or Client.genai_client()).files.upload(file=fn, config={'display_name': fn.name})
    return {'file_data': {'mime_type': f.mime_type, 'file_uri': f.uri}}

