def text_msg(s:str, **kw)->dict:
    return {'text': s}

# %% ../00_core.ipynb
def _mk_content(src, **kw):
    "Create appropriate content data structure based on type of content"
    if isinstance(src,str): return text_msg(src, **kw)
    if isinstance(src, (FunctionResponse, Part)): return src
    else: return media_msg(src, **kw)

# %% ../00_core.ipynb
def mk_msg(content, role='user', **kw):
    if isinstance(content, GenerateContentResponse): role,content = 'model',contents(content)
    if isinstance(content, Content): role,content = content.role,content.parts
    if isinstance(content, dict): role,content = content['role'],content['parts']
    if not isinstance(content, list): content=[Part(text=content) if isinstance(content, str) else content]
    if role == 'user': content = [_mk_content(o, **kw) for o in content]
    return dict(role=role, parts=content)

# %% ../00_core.ipynb
def mk_msgs(msgs:list, **kw):
    "Helper to set 'assistant' role on alternate messages."
    if isinstance(msgs,str): msgs=[msgs]
    return [mk_msg(o, ('user','model')[i%2], **kw) for i,o in enumerate(msgs)]

